// IMPORTANT CAVEAT (read before trusting these numbers): this project has
// no real user-accounts table - FIREBASE_AUTH_ENABLED is false, people just
// type a display name and play. There is no persistent identity to track
// 'a user' across visits. This report approximates activity from ROOMS
// instead: a room touched in the last 24h counts as 'active', a room that
// meets the same staleness rule as the cleanup workflow (finished, or
// older than 6h with no update) counts as 'idle/stale'. It is a proxy, not
// a real per-user active/idle count - if that's genuinely needed, the app
// itself needs a users/ collection written on each session, which is a
// code change, not just a workflow.
const ACTIVE_WINDOW_MS = 24 * 60 * 60 * 1000;
const STALE_MS = 6 * 60 * 60 * 1000;
const now = Date.now();

function summarize(rooms) {
  rooms = rooms || {};
  let active = 0, stale = 0, total = 0;
  const uniquePlayerIds = new Set();
  for (const roomId of Object.keys(rooms)) {
    const room = rooms[roomId] || {};
    total++;
    const age = room.createdAt ? (now - room.createdAt) : Infinity;
    if (room.status === 'finished' || age > STALE_MS) stale++;
    else if (age <= ACTIVE_WINDOW_MS) active++;
    if (room.host?.id) uniquePlayerIds.add(room.host.id);
    if (room.guest?.id) uniquePlayerIds.add(room.guest.id);
  }
  return { total, active, stale, approxDistinctSessionIds: uniquePlayerIds.size };
}

const dond = summarize($input.first().json?.[0]);
const mazad = summarize($input.first().json?.[1]);

return [{
  json: {
    generatedAt: new Date().toISOString(),
    caveat: 'Room-based proxy, not real per-user tracking - no users/ collection exists in this project (auth disabled).',
    deal_or_no_deal: dond,
    mazad: mazad,
    combined: {
      totalRooms: dond.total + mazad.total,
      activeRooms: dond.active + mazad.active,
      staleRoomsPendingCleanup: dond.stale + mazad.stale
    }
  }
}];
